<?php
declare(strict_types=1); require_once __DIR__.'/../src/auth.php'; $token=trim($_GET['token']??$_POST['token']??''); $rec=validate_password_reset_token($token); $error=null;$ok=false;
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $rec=validate_password_reset_token($token); $p=$_POST['password']??'';$c=$_POST['password_confirmation']??''; if(!$rec)$error='Link expirado ou utilizado.'; elseif($p!==$c)$error='As senhas não são iguais.'; elseif(!password_is_strong($p))$error='Use 8 caracteres com maiúscula, minúscula e número.'; else{ db()->beginTransaction(); try{ db()->prepare("UPDATE app_users SET password_hash=:h,password_changed_at=NOW(),must_change_password=false,failed_login_count=0,locked_until=NULL,updated_at=NOW() WHERE id=:i")->execute(['h'=>password_hash($p,PASSWORD_DEFAULT),'i'=>$rec['user_id']]); db()->prepare("UPDATE password_reset_tokens SET used_at=NOW() WHERE id=:i")->execute(['i'=>$rec['token_id']]); db()->commit(); audit_log('password_reset_completed','app_user',$rec['user_id']); $ok=true; }catch(Throwable $e){ db()->rollBack();$error='Não foi possível alterar a senha.'; } } }
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nova senha</title><link rel="icon" href="/assets/images/rs-english-mark-transparent.png" type="image/png"><link rel="stylesheet" href="/assets/css/app.css?v=10.7"></head><body><div class="login-page"><div class="login-box"><h1>Nova senha</h1><?php if($ok):?><div class="list-card"><strong>Senha atualizada.</strong></div><a class="btn btn-primary" style="width:100%" href="/login.php">Entrar</a><?php elseif(!$rec):?><div class="error">Link expirado ou utilizado.</div><?php else:?><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="token" value="<?=htmlspecialchars($token)?>"><div class="form-row"><label>Nova senha</label><input type="password" name="password" required></div><div class="form-row"><label>Confirmar</label><input type="password" name="password_confirmation" required></div><button class="btn btn-primary" style="width:100%">Salvar</button></form><?php endif;?></div></div></body></html>
